    private Border Expand(string title,UIElement content,bool open=false)
    {
        ValidationStep("SETTINGS_SECTION_"+title);
        content.Visibility=open ? Visibility.Visible : Visibility.Collapsed;
        var arrow=new FontIcon { Glyph=open ? "\uE70E" : "\uE70D",FontSize=12,Opacity=.5 };
        var titleText=Text(title,15); titleText.FontWeight=Microsoft.UI.Text.FontWeights.SemiBold;
        var headerContent=new Grid(); headerContent.ColumnDefinitions.Add(new() { Width=new(1,GridUnitType.Star) }); headerContent.ColumnDefinitions.Add(new() { Width=GridLength.Auto }); Place(headerContent,titleText); Place(headerContent,arrow,0,1);
        var header=Button("",()=> { open=!open; content.Visibility=open ? Visibility.Visible : Visibility.Collapsed; arrow.Glyph=open ? "\uE70E" : "\uE70D"; }); header.Content=headerContent;
        Microsoft.UI.Xaml.Automation.AutomationProperties.SetName(header,title);
        header.HorizontalAlignment=HorizontalAlignment.Stretch; header.HorizontalContentAlignment=HorizontalAlignment.Stretch; header.Background=new Microsoft.UI.Xaml.Media.SolidColorBrush(Microsoft.UI.Colors.Transparent); header.BorderThickness=new Thickness(0); header.Padding=new Thickness(0);
        return Card(Stack(header,content),new Thickness(22,12,22,18));
    }
    private static int Int(string text,int min,int max) { if(!int.TryParse(text,out var value) || value<min || value>max) throw new InvalidDataException($"Enter a number from {min} to {max}."); return value; }
    private async Task<bool> ConfirmParentalPinAsync() { var pin=new PasswordBox { Style=(Style)Application.Current.Resources["NullTVPasswordBoxStyle"],Foreground=FieldText(),Background=FieldFill(),BorderBrush=FieldStroke(),CornerRadius=new CornerRadius(10), Header="Current parental PIN" }; if(await DialogAsync("Confirm PIN",pin,"Unlock")!=ContentDialogResult.Primary) return false; var password=pin.Password; var profile=settings.Profile; return await Task.Run(()=>SecretStore.CheckPin(password,profile)); }
    private void RecreatePlayers()
    {
        if(videoGrid==null) return; var resume=playing; StopPlayback(); foreach(var v in surfaces) v.Dispose(); surfaces.Clear(); active.Clear(); videoGrid.Children.Clear(); videoGrid.RowDefinitions.Clear(); videoGrid.ColumnDefinitions.Clear(); multi=false; surface=CreateSurface(); videoGrid.Children.Add(surface); if(emptyLive!=null) { videoGrid.Children.Add(emptyLive); emptyLive.Visibility=resume==null ? Visibility.Visible : Visibility.Collapsed; } if(resume!=null) _=GuardAsync(()=>PlayAsync(resume));
    }
    private async Task EditSourceAsync(Source? original)
    {
        if(original?.Kind is SourceKind.Jellyfin or SourceKind.Emby or SourceKind.Plex) { await EditServerAsync(original); return; }
        var kind=Choice("Source type",new[]{"Xtream","PlaylistUrl","PlaylistFile"},original?.Kind.ToString()??"Xtream"); var name=Field("Source name",original?.Name??""); var address=new PasswordBox { Style=(Style)Application.Current.Resources["NullTVPasswordBoxStyle"],Foreground=FieldText(),Background=FieldFill(),BorderBrush=FieldStroke(),CornerRadius=new CornerRadius(10), Header="Server URL / playlist URL or path",Password=original?.Address??"",MinHeight=44 }; var user=Field("Username",original?.Username??""); var pass=new PasswordBox { Style=(Style)Application.Current.Resources["NullTVPasswordBoxStyle"],Foreground=FieldText(),Background=FieldFill(),BorderBrush=FieldStroke(),CornerRadius=new CornerRadius(10), Header="Password",Password=original?.Password??"",MinHeight=44 }; var epg=new PasswordBox { Style=(Style)Application.Current.Resources["NullTVPasswordBoxStyle"],Foreground=FieldText(),Background=FieldFill(),BorderBrush=FieldStroke(),CornerRadius=new CornerRadius(10), Header="EPG URL override (optional)",Password=original?.EpgOverride??"",MinHeight=44 }; var hours=Field("Refresh interval hours (1–168)",(original?.RefreshHours??12).ToString()); var extension=Choice("Xtream live output",new[]{"ts","m3u8"},original?.LiveExtension??"ts"); var panel=Stack(kind,name,address,AsyncButton("Choose local playlist",async ()=> { var path=await OpenFileAsync(".m3u",".m3u8"); if(path!=null) { address.Password=path; kind.SelectedItem="PlaylistFile"; } }),user,pass,epg,hours,extension);
        if(await DialogAsync(original==null ? "Add source" : "Edit source",Scroll(panel))!=ContentDialogResult.Primary) return;
        if(string.IsNullOrWhiteSpace(name.Text) || string.IsNullOrWhiteSpace(address.Password)) throw new InvalidDataException("A source name and address are required.");
        var s=original??new Source(); s.Kind=Enum.Parse<SourceKind>((string)kind.SelectedItem); s.Name=name.Text.Trim(); s.Address=address.Password.Trim(); s.Username=user.Text; s.Password=pass.Password; s.EpgOverride=epg.Password.Trim(); s.RefreshHours=Int(hours.Text,1,168); s.LiveExtension=(string)extension.SelectedItem;
        if(original==null) settings.Profile.Sources.Add(s); await store.SaveAsync(settings); Navigate("Settings"); await RefreshSourceAsync(s);
    }
    private async Task RefreshSourceAsync(Source s)
    {
        if(s.Kind is SourceKind.Jellyfin or SourceKind.Emby or SourceKind.Plex) { var library=await new MediaServerClient(http).BrowseAsync(s,lifetime.Token); catalogs[s.Id]=library; await store.SaveCacheAsync(s.Id,library); await store.SaveAsync(settings); RebuildItems(); Navigate("Settings"); return; }
        status.Text=$"Testing {s.Name}…"; var service=new SourceService(http,store); var c=await Task.Run(()=>service.RefreshAsync(s,lifetime.Token)); catalogs[s.Id]=c; await store.SaveAsync(settings); RebuildItems(); status.Text=$"{s.Name}: {c.Status} · expiry {c.Expires?.ToLocalTime().ToString("g")??"not supplied"}"; try { epgs[s.Id]=await Task.Run(()=>service.LoadEpgAsync(s,c,lifetime.Token)); await IndexGuidesAsync(); UpdateNowNext(); await store.SaveGuideAsync(s.Id,epgs[s.Id]); } catch(Exception e) { await log.WriteAsync("EPG_FAILED",e); status.Text="Channels loaded; EPG unavailable. Check the source's XMLTV override."; } if(currentTab=="Settings") Navigate("Settings");
    }
    private async Task MapEpgAsync(Source s)
    {
        var channels=items.Where(i=>i.SourceId==s.Id && i.Kind==MediaKind.Live).ToArray(); var channel=Choice("Channel",channels.Select(i=>$"{i.Id} | {i.Name}"),""); var id=Field("XMLTV channel ID");
        if(await DialogAsync("EPG mapping",Stack(channel,id))==ContentDialogResult.Primary && channel.SelectedItem is string value) { s.EpgMappings[value.Split(" | ")[0]]=id.Text.Trim(); await store.SaveAsync(settings); UpdateLive(); }
    }
    private async Task<string?> OpenFileAsync(params string[] extensions) { var picker=new FileOpenPicker(); WinRT.Interop.InitializeWithWindow.Initialize(picker,WinRT.Interop.WindowNative.GetWindowHandle(this)); foreach(var e in extensions) picker.FileTypeFilter.Add(e); var file=await picker.PickSingleFileAsync(); return file?.Path; }
    private async Task<string?> SaveFileAsync(string name,string extension) { var picker=new FileSavePicker { SuggestedFileName=name }; WinRT.Interop.InitializeWithWindow.Initialize(picker,WinRT.Interop.WindowNative.GetWindowHandle(this)); picker.FileTypeChoices.Add("NullTV file",new List<string>{extension}); var file=await picker.PickSaveFileAsync(); return file?.Path; }
    private async Task ExportDiagnosticsAsync()
    {
        var path=await SaveFileAsync("NullTV-diagnostics",".zip"); if(path==null) return;
        var config=new { Version=typeof(MainWindow).Assembly.GetName().Version?.ToString(3),Architecture=System.Runtime.InteropServices.RuntimeInformation.ProcessArchitecture.ToString(),OS=Environment.OSVersion.VersionString,ProfileCount=settings.Profiles.Count,Sources=settings.Profile.Sources.Select(s=>new { s.Kind,s.RefreshHours,HasEpgOverride=s.EpgOverride!="",Status=s.Expires<DateTimeOffset.UtcNow ? "Expired" : "UnknownOrActive" }),settings.Playback.HardwareDecode,settings.Playback.LowLatency,settings.Playback.CacheSeconds,settings.Playback.BufferMiB,Theme=settings.Appearance.Theme };
        using var zip=new ZipArchive(new FileStream(path,FileMode.Create),ZipArchiveMode.Create); var entry=zip.CreateEntry("sanitized-config.json"); await using(var output=entry.Open()) await JsonSerializer.SerializeAsync(output,config,SettingsStore.JsonOptions); var stats=zip.CreateEntry("playback.txt"); await using(var output=new StreamWriter(stats.Open())) await output.WriteAsync(surface?.Player?.Stats()??"No active playback"); var logs=Path.Combine(store.DirectoryPath,"logs"); if(Directory.Exists(logs)) foreach(var file in Directory.EnumerateFiles(logs,"*.log")) { var e=zip.CreateEntry("logs/"+Path.GetFileName(file)); await using var output=e.Open(); await using var input=new FileStream(file,FileMode.Open,FileAccess.Read,FileShare.ReadWrite,8192,true); await input.CopyToAsync(output); } status.Text="Sanitized diagnostics exported. No server URLs, credentials, titles or profile names are included.";
    }
